import{_ as l,a0 as p,w as d,s as r,I as a,x as i,a1 as n,A as t,ao as h}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"使用 Vi/Vim 編輯器：高級概念 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Vi/Vim 編輯器：高級概念 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Vi/Vim 編輯器：高級概念 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Vi/Vim 編輯器：高級概念 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170524 Working with Vi-Vim Editor - Advanced concepts","title":"使用 Vi/Vim 編輯器：高級概念","tag":"201801","desc":""},"relativePath":"201801/20170524 Working with Vi-Vim Editor - Advanced concepts.md","filePath":"[post].md"}'),o={name:"201801/20170524 Working with Vi-Vim Editor - Advanced concepts.md"};function g(k,s,c,b,u,f){const e=p("Link");return d(),r("div",null,[s[18]||(s[18]=a("h1",{id:"使用-vi-vim-編輯器-高級概念",tabindex:"-1"},[i("使用 Vi/Vim 編輯器：高級概念 "),a("a",{class:"header-anchor",href:"#使用-vi-vim-編輯器-高級概念","aria-label":"Permalink to “使用 Vi/Vim 編輯器：高級概念”"},"​")],-1)),s[19]||(s[19]=a("p",null,"早些時候我們已經討論了一些關於 VI/VIM 編輯器的基礎知識，但是 VI 和 VIM 都是非常強大的編輯器，還有很多其他的功能可以和編輯器一起使用。在本教程中，我們將學習 VI/VIM 編輯器的一些高級用法。",-1)),a("p",null,[s[1]||(s[1]=i("（",-1)),s[2]||(s[2]=a("strong",null,"推薦閲讀",-1)),s[3]||(s[3]=i("：[使用 VI 編輯器：基礎知識] ",-1)),n(e,{href:"http://linuxtechlab.com/working-vi-editor-basics/"},{default:t(()=>[...s[0]||(s[0]=[i("1",-1)])]),_:1}),s[4]||(s[4]=i("）",-1))]),s[20]||(s[20]=h(`<h3 id="使用-vi-vim-編輯器打開多個文件" tabindex="-1">使用 VI/VIM 編輯器打開多個文件 <a class="header-anchor" href="#使用-vi-vim-編輯器打開多個文件" aria-label="Permalink to “使用 VI/VIM 編輯器打開多個文件”">​</a></h3><p>要打開多個文件，命令將與打開單個文件相同。我們只要添加第二個文件的名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ vi file1 file2 file 3</span></span></code></pre></div><p>要瀏覽到下一個文件，我們可以（在 vim 命令模式中）使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:n</span></span></code></pre></div><p>或者我們也可以使用</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:e filename</span></span></code></pre></div><h3 id="在編輯器中運行外部命令" tabindex="-1">在編輯器中運行外部命令 <a class="header-anchor" href="#在編輯器中運行外部命令" aria-label="Permalink to “在編輯器中運行外部命令”">​</a></h3><p>我們可以在 vi 編輯器內部運行外部的 Linux/Unix 命令，也就是説不需要退出編輯器。要在編輯器中運行命令，如果在插入模式下，先返回到命令模式，我們使用 BANG 也就是 <code>!</code> 接着是需要使用的命令。運行命令的語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:! command</span></span></code></pre></div><p>這是一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:! df -H</span></span></code></pre></div><h3 id="根據模板搜索" tabindex="-1">根據模板搜索 <a class="header-anchor" href="#根據模板搜索" aria-label="Permalink to “根據模板搜索”">​</a></h3><p>要在文本文件中搜索一個單詞或模板，我們在命令模式下使用以下兩個命令：</p><ul><li>命令 <code>/</code> 代表正向搜索模板</li><li>命令 <code>?</code> 代表正向搜索模板</li></ul><p>這兩個命令都用於相同的目的，唯一不同的是它們搜索的方向。一個例子是：</p><p>如果在文件的開頭向前搜索，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:/ search pattern</span></span></code></pre></div><p>如果在文件末尾向後搜索，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:? search pattern</span></span></code></pre></div><h3 id="搜索並替換一個模式" tabindex="-1">搜索並替換一個模式 <a class="header-anchor" href="#搜索並替換一個模式" aria-label="Permalink to “搜索並替換一個模式”">​</a></h3><p>我們可能需要搜索和替換我們的文本中的單詞或模式。我們不是從整個文本中找到單詞的出現的地方並替換它，我們可以在命令模式中使用命令來自動替換單詞。使用搜索和替換的語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:s/pattern_to_be_found/New_pattern/g</span></span></code></pre></div><p>假設我們想要將單詞 “alpha” 用單詞 “beta” 代替，命令就是這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:s/alpha/beta/g</span></span></code></pre></div><p>如果我們只想替換第一個出現的 “alpha”，那麼命令就是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ :s/alpha/beta/</span></span></code></pre></div><h3 id="使用-set-命令" tabindex="-1">使用 set 命令 <a class="header-anchor" href="#使用-set-命令" aria-label="Permalink to “使用 set 命令”">​</a></h3><p>我們也可以使用 set 命令自定義 vi/vim 編輯器的行為和外觀。下面是一些可以使用 set 命令修改 vi/vim 編輯器行為的選項列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:set ic  &#39; 在搜索時忽略大小寫</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set smartcase &#39; 搜索強制區分大小寫</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set nu &#39; 在每行開始顯示行號</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set hlsearch &#39; 高亮顯示匹配的單詞</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set ro &#39; 將文件類型更改為只讀</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set term &#39; 打印終端類型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set ai &#39; 設置自動縮進</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set noai &#39; 取消自動縮進</span></span></code></pre></div><p>其他一些修改 vi 編輯器的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:colorscheme &#39; 用來改變編輯器的配色方案 。（僅適用於 VIM 編輯器）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:syntax on &#39; 為 .xml、.html 等文件打開顏色方案。（僅適用於VIM編輯器）</span></span></code></pre></div><p>這篇結束了本系列教程，請在下面的評論欄中提出你的疑問/問題或建議。</p><hr>`,34)),a("p",null,[s[6]||(s[6]=i("via: ",-1)),n(e,{href:"http://linuxtechlab.com/working-vivim-editor-advanced-concepts/"},{default:t(()=>[...s[5]||(s[5]=[i("http://linuxtechlab.com/working-vivim-editor-advanced-concepts/",-1)])]),_:1})]),a("p",null,[s[10]||(s[10]=i("作者：",-1)),n(e,{href:"http://linuxtechlab.com/author/shsuain/"},{default:t(()=>[...s[7]||(s[7]=[i("Shusain",-1)])]),_:1}),s[11]||(s[11]=i(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[8]||(s[8]=[i("geekpi",-1)])]),_:1}),s[12]||(s[12]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[9]||(s[9]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[i("LCTT",-1)])]),_:1}),s[16]||(s[16]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[i("Linux中國",-1)])]),_:1}),s[17]||(s[17]=i(" 榮譽推出",-1))])])}const C=l(o,[["render",g]]);export{V as __pageData,C as default};
